def get_number(prompt):
    """Get a number as input from the user."""
    while True:
        try:
            number = float(input(prompt))
            return number
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Get an operation as input from the user."""
    operations = {"+": "addition", "-": "subtraction", "*": "multiplication", "/": "division"}
    while True:
        operation = input("Enter an operation (+, -, *, /): ").lower()
        if operation in operations:
            return operation, operations[operation]
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on two numbers and return the result."""
    if operation == "addition":
        return num1 + num2
    elif operation == "subtraction":
        return num1 - num2
    elif operation == "multiplication":
        return num1 * num2
    elif operation == "division":
        return num1 / num2

def main():
    """Get two numbers and an operation from the user, perform the operation, and print the result."""
    num1 = get_number("Enter the first number: ")
    operation, operation_name = get_operation()
    num2 = get_number(f"Enter the second number for {operation_name}: ")
    result = perform_operation(num1, num2, operation)
    print(f"The result of {num1} {operation} {num2} is {result}.")

if __name__ == "__main__":
    main()
